      "name": "Finsupp.linearCombination_mapDomain",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (R : Type u_5) [inst : Semiring R] {α' : Type u_7} {M' : Type u_8} [inst_1 : AddCommMonoid M']\n  [inst_2 : Module R M'] {v' : α' → M'} (f : α → α') (l : α →₀ R),\n  (Finsupp.linearCombination R v') (Finsupp.mapDomain f l) = (Finsupp.linearCombination R (v' ∘ f)) l"
    },
    {
      "name": "LinearMap.map_finsupp_linearCombination",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} {N : Type u_3} [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]\n  [inst_3 : AddCommMonoid N] [inst_4 : Module R N] (f : M →ₗ[R] N) {ι : Type u_4} {g : ι → M} (l : ι →₀ R),\n  f ((Finsupp.linearCombination R g) l) = (Finsupp.linearCombination R (⇑f ∘ g)) l"
    },
    {
      "name": "Finsupp.linearCombination_linear_comp",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} (R : Type u_5) [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]\n  {M' : Type u_8} [inst_3 : AddCommMonoid M'] [inst_4 : Module R M'] {v : α → M} (f : M →ₗ[R] M'),\n  Finsupp.linearCombination R (⇑f ∘ v) = f ∘ₗ Finsupp.linearCombination R v"
    },
    {
      "name": "Finsupp.linearCombination_embDomain",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (R : Type u_5) [inst : Semiring R] {α' : Type u_7} {M' : Type u_8} [inst_1 : AddCommMonoid M']\n  [inst_2 : Module R M'] {v' : α' → M'} (f : α ↪ α') (l : α →₀ R),\n  (Finsupp.linearCombination R v') (Finsupp.embDomain f l) = (Finsupp.linearCombination R (v' ∘ ⇑f)) l"
    },
    {
      "name": "Finsupp.linearCombination_comp_lmapDomain",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (R : Type u_5) [inst : Semiring R] {α' : Type u_7} {M' : Type u_8} [inst_1 : AddCommMonoid M']\n  [inst_2 : Module R M'] {v' : α' → M'} (f : α → α'),\n  Finsupp.linearCombination R v' ∘ₗ Finsupp.lmapDomain R R f = Finsupp.linearCombination R (v' ∘ f)"
    }
